<?php
declare(strict_types=1);
require_once __DIR__.'/config/bi_step22.php';$error=null;$m=[];$suppliers=[];$user=[];$p=bi_step22_period($_GET['month']??null);$glAr=0.0;$glAp=0.0;$glInv=0.0;
try{$pdo=business_db();bi_step22_ensure($pdo);$user=bi_step22_guard($pdo,'bi.view');$ctx=bi_step22_context($pdo);$orgId=(int)$ctx['organization_id'];$m=bi_step22_metrics($pdo,$orgId,$p['start'],$p['end']);$suppliers=bi_step22_top_suppliers($pdo,$orgId,$p['start'],$p['end'],12);$balance=function(string $role,string $normal)use($pdo,$orgId):float{$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN ?='debit' THEN l.debit_amount-l.credit_amount ELSE l.credit_amount-l.debit_amount END),0) FROM finance_ledger_accounts a JOIN finance_journal_lines l ON l.ledger_account_id=a.id AND l.organization_id=a.organization_id JOIN finance_journals j ON j.id=l.journal_id AND j.organization_id=l.organization_id WHERE a.organization_id=? AND a.system_role=? AND j.status='posted'");$s->execute([$normal,$orgId,$role]);return(float)$s->fetchColumn();};$glAr=$balance('accounts_receivable','debit');$glAp=$balance('accounts_payable','credit');$glInv=$balance('inventory_asset','debit');}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Exposure BI - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"><link rel="stylesheet" href="assets/bi_step22.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="executive_bi.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 22 • Financial & Stock Exposure</small></span></a><div class="os-top-actions"><a class="os-btn" href="finance_receivable_payable.php">AR/AP Reconcile</a><a class="os-btn primary" href="executive_bi.php">Executive BI</a></div></div></header><main class="os-main" style="max-width:1500px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">CURRENT EXPOSURE</div><h1>Receivables, payables and stock risk in one management view.</h1><p>These are current balances and stock conditions. They are intentionally not labeled as monthly revenue or expense.</p></section><?php if($error):?><div class="pp-alert bad"><?=bi_step22_h($error)?></div><?php else:?><section class="bi-kpis"><div class="bi-kpi"><small>Customer Receivable</small><strong><?=bi_step22_money($m['customer_receivable'])?></strong><span>Operational fulfillment ledger</span></div><div class="bi-kpi"><small>Supplier Payable</small><strong><?=bi_step22_money($m['supplier_payable'])?></strong><span><?=$m['overdue_supplier_bills']?> overdue bill(s)</span></div><div class="bi-kpi"><small>Customer Credit Due</small><strong><?=bi_step22_money($m['customer_credit_due'])?></strong><span>post-return/refund balance</span></div><div class="bi-kpi"><small>Known Stock Value</small><strong><?=bi_step22_money($m['inventory_value_known'])?></strong><span>cost coverage <?=$m['inventory_cost_coverage']===null?'N/A':number_format((float)$m['inventory_cost_coverage'],1).'%'?></span></div><div class="bi-kpi"><small>Stock Risk</small><strong><?=$m['out_of_stock']?> / <?=$m['low_stock']?> / <?=$m['expiry_risk']?></strong><span>out • low • expiry-window</span></div></section><section class="bi-grid"><article class="os-card bi-span-6"><div class="os-title-row"><div><h2>Operational vs General Ledger</h2><p>Variances highlight reconciliation work; they are not silently corrected.</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Control</th><th>Operational</th><th>GL</th><th>Difference</th></tr></thead><tbody><tr><td>Accounts Receivable</td><td><?=bi_step22_money($m['customer_receivable'])?></td><td><?=bi_step22_money($glAr)?></td><td><?=bi_step22_money($glAr-$m['customer_receivable'])?></td></tr><tr><td>Accounts Payable</td><td><?=bi_step22_money($m['supplier_payable'])?></td><td><?=bi_step22_money($glAp)?></td><td><?=bi_step22_money($glAp-$m['supplier_payable'])?></td></tr><tr><td>Inventory Asset</td><td><?=bi_step22_money($m['inventory_value_known'])?> known</td><td><?=bi_step22_money($glInv)?></td><td><?=$m['inventory_cost_coverage']!==null&&$m['inventory_cost_coverage']>=99.99?bi_step22_money($glInv-$m['inventory_value_known']):'N/A — cost coverage incomplete'?></td></tr></tbody></table></div></article><article class="os-card bi-span-6"><div class="os-title-row"><div><h2>Inventory Risk</h2><p>Uses explicit reorder levels and configured expiry-alert windows.</p></div></div><div class="bi-note"><b>Out of stock</b><strong style="float:right"><?=$m['out_of_stock']?></strong><small class="bi-muted">Tracked listings with zero sellable quantity.</small></div><div class="bi-note"><b>Low stock</b><strong style="float:right"><?=$m['low_stock']?></strong><small class="bi-muted">Only listings with an explicit reorder level &gt; 0.</small></div><div class="bi-note"><b>Expiry risk</b><strong style="float:right"><?=$m['expiry_risk']?></strong><small class="bi-muted">Batches inside each product's configured alert window.</small></div><div class="bi-note"><b>Sellable units</b><strong style="float:right"><?=bi_step22_num($m['inventory_units'],3)?></strong></div></article><article class="os-card bi-span-12"><div class="os-title-row"><div><h2>Supplier Exposure • <?=bi_step22_h($p['label'])?></h2><p>Period bill volume plus current outstanding by suppliers active in the selected month.</p></div></div><div class="bi-table-wrap"><table class="bi-table"><thead><tr><th>Supplier</th><th>Bills</th><th>Period Billed</th><th>Paid</th><th>Current Outstanding</th></tr></thead><tbody><?php if(!$suppliers):?><tr><td colspan="5">No supplier bills in this period.</td></tr><?php endif;?><?php foreach($suppliers as $r):?><tr><td><?=bi_step22_h($r['supplier_name'])?></td><td><?=$r['bills']?></td><td><?=bi_step22_money($r['billed'])?></td><td><?=bi_step22_money($r['paid'])?></td><td><?=bi_step22_money($r['outstanding'])?></td></tr><?php endforeach;?></tbody></table></div></article></section><?php endif;?></main></body></html>